WITH recent_subscriptions AS (SELECT * FROM subscriptions WHERE start_date <= '2025-10-01' AND (start_date < '2024-05-07' OR customer_id IN (4, 30))), summary AS (SELECT MONTH(start_date) AS start_month, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(status))) AS status_values, MIN(start_date) AS min_start_date FROM recent_subscriptions GROUP BY MONTH(start_date)) SELECT * FROM summary ORDER BY min_start_date;
